// v4 ScreenSpec -> v5 ScreenProgram (pure). Mirrors engine/v5/convert.py exactly (tests compare
// both against fixtures generated by the Python function), so confirmed v4 prompts keep working.
import type { ScreenProgram } from "spec";

type V4Cond = { id: string; role: "filter" | "event" | "stop"; kind: "field" | "indicator"; name: string; params?: Record<string, unknown>; op: string; value?: unknown; dir?: "long" | null };
export type V4Spec = {
  structure: "literal" | "t1_literal"; selection_point?: { session_of_week: number; at: "open" | "close" } | null;
  conditions: V4Cond[]; stop?: { from: string } | null; risk_cap_pct?: number | null;
  near_miss?: { max_failed: number } | null; t1_window?: { length_sessions: number; offsets: number[] } | null;
};

export function v4ToV5(spec: V4Spec): Omit<ScreenProgram, "source_phrases" | "needs_input" | "unsupported" | "ignored" | "unrecognised" | "answers"> {
  const ids: string[] = [];
  const conditions = spec.conditions.map((c) => {
    const lhs = c.kind === "field" ? { field: c.name, params: { ...(c.params ?? {}) } } : { ind: c.name, params: { ...(c.params ?? {}) }, tf: "1W" };
    const d: any = { id: c.id, lhs, op: c.op };
    if (c.value !== undefined && c.value !== null) d.value = c.value;
    if (c.op === "flip") { d.dir = c.dir ?? "long"; d.within_bars = 1; }
    if (c.role !== "stop") ids.push(c.id);
    return d;
  });
  const ev: any = { mode: spec.structure, timeframe: "1W", bar: "last_completed" };
  if (spec.structure === "t1_literal" && spec.t1_window) ev.t1_window = { ...spec.t1_window };
  const set: any = { id: "S1", from: "universe", label: "v4 spec", eval: ev, where: { all: ids } };
  if (spec.near_miss) set.near_miss = { max_failed: spec.near_miss.max_failed };
  const actions: any[] = [];
  if (spec.stop) {
    const sp = spec.selection_point;
    const entry = sp && sp.session_of_week === 1 && sp.at === "open" ? { at: "next_open" }
      : sp ? { at: "session", session_of_week: sp.session_of_week, session_at: sp.at } : { at: "signal_close" };
    actions.push({ id: "A1", type: "trade_plan", set: "S1", entry, stop: { from: spec.stop.from }, confidence: { method: "conditions_met_count" },
      ...(spec.risk_cap_pct != null ? { risk_cap_pct: spec.risk_cap_pct } : {}) });
  }
  return { program_version: 5, universe: { source: "nse_all" }, sets: [set], conditions, actions };
}
